		item.AllowPlainText = allow_plain_textValue
		allow_websocketValue, ok := webSocketSecurityDecodeRequiredBool(object["allow_websocket"], location+" allow_websocket", &diagnostics)
		if !ok {
			continue
		}
		item.AllowWebsocket = allow_websocketValue
		block_attacksValue, ok := webSocketSecurityDecodeRequiredBool(object["block_attacks"], location+" block_attacks", &diagnostics)
		if !ok {
			continue
		}
		item.BlockAttacks = block_attacksValue
