func webSocketSecurityRuleListWrapperValue(owned webSocketSecurityRuleListOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(webSocketSecurityRuleListWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for itemIndex, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		objectValues["allow_binary_text"] = types.BoolValue(item.AllowBinaryText)
		objectValues["allow_plain_text"] = types.BoolValue(item.AllowPlainText)
		objectValues["allow_websocket"] = types.BoolValue(item.AllowWebsocket)
		objectValues["block_attacks"] = types.BoolValue(item.BlockAttacks)
		objectValues["block_extensions"] = types.BoolValue(item.BlockExtensions)
		objectValues["max_frm_size"] = types.Int64Value(item.MaxFrmSize)
		objectValues["max_msg_size"] = types.Int64Value(item.MaxMsgSize)
		objectValues["name"] = types.StringValue(item.Name)

		origin_listWrapper := types.ObjectNull(webSocketSecurityRuleListOriginListWrapperAttributeTypes)
		origin_listMask := subItemOwnedMasks["OriginList"]
		if itemIndex < len(origin_listMask) && origin_listMask[itemIndex] {
			origin_listWrapperComputed, origin_listWrapperDiags := webSocketSecurityRuleListOriginListWrapperValue(item.OriginList)
			diagnostics.Append(origin_listWrapperDiags...)
			origin_listWrapper = origin_listWrapperComputed
		}
		objectValues["origin_list"] = origin_listWrapper
		objectValues["url"] = types.StringValue(item.URL)
		object, objectDiagnostics := types.ObjectValue(webSocketSecurityRuleListItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: webSocketSecurityRuleListItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(webSocketSecurityRuleListWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
