func webSocketSecurityOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (webSocketSecurityOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return webSocketSecurityOwnershipSet{RuleList: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return webSocketSecurityOwnershipSet{RuleList: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return webSocketSecurityOwnershipSet{RuleList: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown WebSocket security ownership", "The configs ownership state was unknown while flattening.")
		return webSocketSecurityOwnershipSet{RuleList: false}, diagnostics
	}
	var configs webSocketSecurityConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return webSocketSecurityOwnershipSet{RuleList: !configs.RuleList.IsNull()}, diagnostics
}
